/* ========================================
   IDEA AGENT — Settings Module
   Theme, API key, preferences
   ======================================== */

var Settings = {
  render() {
    const settings = Store.getSettings();
    return `<div class="page-header"><h1>⚙️ Cài đặt</h1></div><div class="settings-section animate-slide-up"><h2>🎨 Giao diện</h2><div class="settings-row"><div><div class="settings-row-label">Dark Mode</div><div class="settings-row-desc">Chế độ tối</div></div><label class="toggle-switch"><input type="checkbox" id="settings-theme" ${settings.theme === 'dark' ? 'checked' : ''} onchange="Settings.toggleTheme(this.checked)"><span class="toggle-slider"></span></label></div></div><div class="settings-section animate-slide-up" style="animation-delay:0.05s"><h2>🤖 DeepSeek AI</h2><div class="settings-row"><div style="flex:1"><div class="settings-row-label">🔑 API Key</div><div class="settings-row-desc">Lấy key từ <a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noopener" style="color:var(--primary)">DeepSeek Platform</a></div></div></div><div style="display:flex;gap:var(--space-sm);margin-top:var(--space-sm)"><input type="password" class="form-input" id="settings-api-key" value="${settings.geminiApiKey || ''}" placeholder="sk-..." aria-label="DeepSeek API Key"><button class="btn btn-secondary" aria-label="Hiện/ẩn API Key" onclick="Settings.toggleApiKeyVisibility()">👁️</button><button class="btn btn-primary" onclick="Settings.saveApiKey()">Lưu</button></div><div style="margin-top:var(--space-xs);font-size:0.75rem;color:var(--text-muted)">🔒 Lưu cục bộ trên thiết bị (localStorage).</div><div class="settings-row" style="margin-top:var(--space-md);padding:var(--space-sm) var(--space-md);background:var(--bg-tertiary);border-radius:var(--radius-md)"><div style="flex:1"><div class="settings-row-label" style="font-size:0.85rem">${GoogleAuth.isSignedIn && GoogleAuth.userInfo ? '🟢 ' + Utils.escapeHtml(GoogleAuth.userInfo.email) : '👤 Đăng nhập Google (tên & avatar)'}</div></div><div>${GoogleAuth.isSignedIn ? '<button class="btn btn-secondary btn-sm" onclick="GoogleAuth.signOut()">Đăng xuất</button>' : '<button class="btn btn-secondary btn-sm" onclick="GoogleAuth.signIn()">Đăng nhập</button>'}</div></div><div class="settings-row" style="margin-top:var(--space-sm)"><div><div class="settings-row-label">Model</div><div class="settings-row-desc">Model AI tạo bản thảo</div></div><select class="form-select" id="settings-model" style="width:200px" onchange="Settings.saveModel(this.value)"><option value="deepseek-chat" ${(settings.geminiModel === 'deepseek-chat' || !settings.geminiModel) ? 'selected' : ''}>DeepSeek V3</option><option value="deepseek-reasoner" ${settings.geminiModel === 'deepseek-reasoner' ? 'selected' : ''}>DeepSeek R1</option></select></div><div class="settings-row"><div><div class="settings-row-label">Auto Draft</div><div class="settings-row-desc">Tự tạo bản thảo khi lưu ý tưởng</div></div><label class="toggle-switch"><input type="checkbox" id="settings-auto-draft" ${settings.autoGenerateDraft ? 'checked' : ''} onchange="Settings.toggleAutoDraft(this.checked)"><span class="toggle-slider"></span></label></div><div style="margin-top:var(--space-md)"><button class="btn btn-secondary btn-sm" onclick="Settings.testConnection()">🧪 Test kết nối AI</button></div></div><div class="settings-section animate-slide-up" style="animation-delay:0.1s"><h2>📝 Mặc định</h2><div class="settings-row"><div><div class="settings-row-label">Danh mục mặc định</div><div class="settings-row-desc">Chọn sẵn khi tạo ý tưởng</div></div><select class="form-select" id="settings-default-cat" style="width:180px" onchange="Settings.saveDefaultCategory(this.value)">${Utils.renderOptions(Utils.categories, settings.defaultCategory)}</select></div></div><div class="settings-section animate-slide-up" style="animation-delay:0.15s"><h2>💾 Dữ liệu</h2><div class="settings-row"><div><div class="settings-row-label">Export tất cả</div><div class="settings-row-desc">Tải file JSON sao lưu ý tưởng</div></div><button class="btn btn-secondary btn-sm" onclick="Settings.exportAll()">${Utils.icon('export', 16)} Export JSON</button></div><div class="settings-row"><div><div class="settings-row-label">Import dữ liệu</div><div class="settings-row-desc">Khôi phục từ file JSON đã tải</div></div><div><input type="file" id="import-file" accept=".json" style="display:none" onchange="Settings.importFile(this.files[0])"><button class="btn btn-secondary btn-sm" onclick="document.getElementById('import-file').click()">📥 Import JSON</button></div></div><div class="settings-row"><div><div class="settings-row-label" style="color:var(--danger)">Xóa toàn bộ</div><div class="settings-row-desc">Không thể hoàn tác sau khi xóa!</div></div><button class="btn btn-danger btn-sm" onclick="Settings.clearAll()">${Utils.icon('delete', 16)} Xóa tất cả</button></div></div><div class="settings-section animate-slide-up" style="animation-delay:0.2s"><h2>ℹ️ Thông tin</h2><div style="font-size:0.85rem;color:var(--text-secondary);line-height:1.7"><strong>Idea Agent</strong> v2.0<br>Hệ thống ghi nhận & phát triển ý tưởng · DeepSeek AI<br><span style="color:var(--text-muted)">Dữ liệu lưu trữ tại localStorage trên thiết bị</span></div></div>`;
  },

  // ========================
  // THEME
  // ========================

  toggleTheme(isDark) {
    const theme = isDark ? 'dark' : 'light';
    document.documentElement.setAttribute('data-theme', theme);
    Store.updateSettings({ theme });
    App.updateThemeIcon();
  },

  // ========================
  // AI API
  // ========================

  saveApiKey() {
    const input = document.getElementById('settings-api-key');
    if (!input) return;
    const key = input.value.trim();
    Store.updateSettings({ geminiApiKey: key });
    Utils.showToast(key ? '✅ API Key đã lưu' : '⚠️ API Key đã xóa', key ? 'success' : 'info');
    App.updateAIStatusBadge();
  },

  toggleApiKeyVisibility() {
    const input = document.getElementById('settings-api-key');
    if (input) {
      input.type = input.type === 'password' ? 'text' : 'password';
    }
  },

  saveModel(model) {
    Store.updateSettings({ geminiModel: model });
    Utils.showToast(`Model: ${model}`, 'info');
  },

  async testConnection() {
    const settings = Store.getSettings();

    if (!settings.geminiApiKey) {
      Utils.showToast('Vui lòng nhập API Key trước', 'error');
      return;
    }

    Utils.showToast('🧪 Đang kiểm tra kết nối AI...', 'info');

    try {
      const result = await AI.call('Trả lời ngắn gọn bằng tiếng Việt: Xin chào, bạn là AI gì?', settings);
      Utils.showToast('✅ Kết nối thành công! ' + result.substring(0, 80), 'success');
    } catch (err) {
      Utils.showToast('❌ Lỗi: ' + err.message, 'error');
    }
  },

  toggleAutoDraft(enabled) {
    Store.updateSettings({ autoGenerateDraft: enabled });
    Utils.showToast(enabled ? '✅ Auto Draft bật' : '⚠️ Auto Draft tắt', enabled ? 'success' : 'info');
  },

  // ========================
  // DEFAULT CATEGORY
  // ========================

  saveDefaultCategory(cat) {
    Store.updateSettings({ defaultCategory: cat });
    Utils.showToast(`Danh mục mặc định: ${Utils.getCategoryLabel(cat)}`, 'info');
  },

  // ========================
  // DATA MANAGEMENT
  // ========================

  exportAll() {
    const data = Store.exportData();
    const date = new Date().toISOString().split('T')[0];
    Utils.downloadFile(data, `idea-agent-backup-${date}.json`, 'application/json');
    Utils.showToast('📥 Đã export dữ liệu', 'success');
  },

  importFile(file) {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const success = Store.importData(e.target.result);
      if (success) {
        Utils.showToast('✅ Import thành công! Tải lại trang...', 'success');
        setTimeout(() => location.reload(), 1500);
      } else {
        Utils.showToast('❌ File không hợp lệ', 'error');
      }
    };
    reader.readAsText(file);
  },

  clearAll() {
    if (confirm('⚠️ XÓA TOÀN BỘ dữ liệu? Hãy Export backup trước.') && confirm('Xác nhận lần cuối: XÓA TẤT CẢ?')) {
      Store.clearAll();
      Utils.showToast('🗑️ Đã xóa toàn bộ dữ liệu', 'info');
      setTimeout(() => location.reload(), 1000);
    }
  },
};
